import{_ as t,C as n,o as r,c as d,j as a,a as o,E as l,ai as i}from"./chunks/framework.XEs52zTF.js";const C=JSON.parse('{"title":"张量分块实验室","description":"","frontmatter":{"title":"张量分块实验室"},"headers":[],"relativePath":"tensor-lab.md","filePath":"tensor-lab.md"}'),p={name:"tensor-lab.md"};function c(h,e,m,u,b,T){const s=n("TensorLab",!0);return r(),d("div",null,[e[0]||(e[0]=a("h1",{id:"张量分块实验室-改变调度-不改变结果",tabindex:"-1"},[o("张量分块实验室：改变调度，不改变结果 "),a("a",{class:"header-anchor",href:"#张量分块实验室-改变调度-不改变结果","aria-label":'Permalink to "张量分块实验室：改变调度，不改变结果"'},"​")],-1)),e[1]||(e[1]=a("p",null,"矩阵乘的数学定义很短，快慢却取决于循环如何组织，以及数据是否被反复搬运。这个实验把一个矩阵乘拆成小块，观察一次调度如何选择 A、B、C 的区域，最后用朴素实现检查完整结果。",-1)),e[2]||(e[2]=a("p",null,[o("它是浏览器里的教学模型，不是 GPU 模拟器或真实性能基准。先读"),a("a",{href:"./chapter24.html"},"第 24 章"),o("的张量与调度，再来操作会更容易理解。")],-1)),l(s),e[3]||(e[3]=i(`<h2 id="高亮区域表示什么" tabindex="-1">高亮区域表示什么 <a class="header-anchor" href="#高亮区域表示什么" aria-label="Permalink to &quot;高亮区域表示什么&quot;">​</a></h2><p>用半开区间 <code>起点:终点</code> 表示索引范围。例如分块尺寸为 2 时：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C[0:2, 0:2] += A[0:2, 0:2] × B[0:2, 0:2]</span></span>
<span class="line"><span>C[0:2, 0:2] += A[0:2, 2:4] × B[2:4, 0:2]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>第一步只累加 k=0、1 对 C 左上区域的贡献；第二步补上 k=2、3 的贡献，此时该 C 小块才完整。随后处理 C 的下一个区域。不能把中间状态误认为最终矩阵。</p><p>调度循环依次枚举 <code>i0</code>、<code>j0</code>、<code>k0</code>；每个小块内部仍执行标量 <code>C[i][j] += A[i][k] * B[k][j]</code>。实验的整数很小，计算结果在浏览器整数精确表示范围内；它没有借助浮点重结合掩盖数值误差。</p><h2 id="加载次数采用什么假设" tabindex="-1">加载次数采用什么假设 <a class="header-anchor" href="#加载次数采用什么假设" aria-label="Permalink to &quot;加载次数采用什么假设&quot;">​</a></h2><p>对 N×N 矩阵、T×T 分块，本模型假设每个块步骤把 A、B 的两个小块各加载一次，块内运算完全复用这些输入。每步加载 <code>2T²</code> 个元素，共有 <code>(N/T)³</code> 步，所以总计 <code>2N³/T</code> 次输入元素加载。无复用的标量参考模型为 <code>2N³</code>，两者比值为 T。</p><p>算术仍然执行 <code>2N³</code> 次标量操作，把一次乘法和一次加法各记作一次。默认 N=4、T=2 时，全部完成后显示 8 个块步骤、64 次理想输入加载、128 次算术操作，复用对比为 2 倍。</p><p>这个计数没有包含 C 的读写、真实缓存、寄存器溢出、数据对齐、同步、向量指令或矩阵指令。它也没有统计浏览器真实内存访问。T 更大不保证实机更快：超过缓存/寄存器容量、降低并行度或引入边界处理都可能抵消复用收益。因此这里只能用它解释数据复用的方向，不能据此宣称某段 GPU 代码快了 T 倍。</p><h2 id="三个实验与验收" tabindex="-1">三个实验与验收 <a class="header-anchor" href="#三个实验与验收" aria-label="Permalink to &quot;三个实验与验收&quot;">​</a></h2><ol><li>用相同 N，分别选择 T=1、2、4 并运行到底。核对 C 逐元素相同，而加载模型改变。</li><li>在 T=2 下逐步执行两次。为什么 C 只有左上小块可能非零，其他位置仍是零？</li><li>将 N 从 4 改为 8。观察算术操作为何增长 8 倍，而不是 4 倍。</li></ol><details><summary>答案与解释</summary><p>相同 N 对应相同数学问题，调度只改变计算分组，所以结果相同。两次累加都属于同一个 <code>(i0,j0)</code>，只是 k 区间不同，其他 C 区域还没被计算。N 翻倍会把三重循环的每层迭代数都翻倍，算术量增长 <code>2³=8</code> 倍；矩阵存储量只增长 4 倍。</p></details><p>下一步把第 24 章的 Python 参考实现改成可处理非整除尺寸，再用实际工具观察 IR。将 T=3 用于 N=8 时，最后一块需要边界条件或掩码；本实验只提供可以整除的组合，避免把边界条件藏起来。</p>`,13))])}const _=t(p,[["render",c]]);export{C as __pageData,_ as default};
